VALUES
('MEAL-001', 'شوفان الزبادي بالموز والتوت', 'Banana Berry Yogurt Oats', 'وجبة شوفان الزبادي بالموز والتوت محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Banana Berry Yogurt Oats meal calculated from the listed ingredient weights.', 'breakfast'::public.meal_type, ARRAY['fat_loss','maintenance','muscle_gain']::text[], ARRAY['vegetarian','high_fiber']::text[], ARRAY['milk']::text[], 450, 27, 70, 6.9, 378, 'g', 1, ARRAY['ضع رقائق الشوفان في وعاء.','أضف الزبادي اليوناني واخلط حتى يتجانس.','أضف شرائح الموز والتوت، ثم رشّ بذور الشيا وقدّم.']::text[], ARRAY['Add the dry oats to a bowl.','Mix in the Greek yogurt until combined.','Top with sliced banana, berries, and chia seeds. Serve.']::text[], 8, '/nutrition/meals/MEAL-001/cover.webp', '/nutrition/meals/MEAL-001/cover-thumb.webp', 'images/MEAL-001.png', 'ready'::public.meal_image_status, 'شوفان الزبادي بالموز والتوت', 'Banana Berry Yogurt Oats', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "20_29", "carb_band_g": "high", "fat_band_g": "low", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 435, "macro_energy_kcal": 450, "macro_vs_ingredient_delta_pct": 3.5, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 1),
('MEAL-002', 'توست الأفوكادو والبيض', 'Egg & Avocado Toast', 'وجبة توست الأفوكادو والبيض محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Egg & Avocado Toast meal calculated from the listed ingredient weights.', 'breakfast'::public.meal_type, ARRAY['maintenance','muscle_gain']::text[], ARRAY[]::text[], ARRAY['egg','gluten']::text[], 474, 24.9, 42.1, 22.9, 320, 'g', 1, ARRAY['حمّص خبز القمح الكامل.','اهرس الأفوكادو ومدّه على التوست.','أضف البيض المطبوخ وشرائح الطماطم وقدّم.']::text[], ARRAY['Toast the whole-wheat bread.','Mash the avocado and spread it on the toast.','Add the cooked egg and tomato slices. Serve.']::text[], 12, '/nutrition/meals/MEAL-002/cover.webp', '/nutrition/meals/MEAL-002/cover-thumb.webp', 'images/MEAL-002.png', 'ready'::public.meal_image_status, 'توست الأفوكادو والبيض', 'Egg & Avocado Toast', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "20_29", "carb_band_g": "moderate", "fat_band_g": "high", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 463, "macro_energy_kcal": 474, "macro_vs_ingredient_delta_pct": 2.4, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 2),
('MEAL-003', 'أومليت السبانخ مع الخبز', 'Spinach Omelet with Toast', 'وجبة أومليت السبانخ مع الخبز محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Spinach Omelet with Toast meal calculated from the listed ingredient weights.', 'breakfast'::public.meal_type, ARRAY['fat_loss','maintenance']::text[], ARRAY['high_protein']::text[], ARRAY['egg','gluten']::text[], 414, 34.6, 27.7, 18.3, 415, 'g', 1, ARRAY['سخّن زيت الزيتون في مقلاة.','شوّح السبانخ والطماطم ثم أضف البيض الكامل وبياض البيض.','اطوِ الأومليت وقدّمه مع خبز القمح الكامل.']::text[], ARRAY['Heat the olive oil in a pan.','Sauté the spinach and tomato, then add the whole egg and egg whites.','Fold the omelet and serve with the whole-wheat bread.']::text[], 15, '/nutrition/meals/MEAL-003/cover.webp', '/nutrition/meals/MEAL-003/cover-thumb.webp', 'images/MEAL-003.png', 'ready'::public.meal_image_status, 'أومليت السبانخ مع الخبز', 'Spinach Omelet with Toast', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "300_449", "protein_band_g": "30_39", "carb_band_g": "moderate", "fat_band_g": "moderate", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 413, "macro_energy_kcal": 414, "macro_vs_ingredient_delta_pct": 0.2, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 3),
('MEAL-004', 'وعاء الكينوا والزبادي والتفاح', 'Apple Quinoa Yogurt Bowl', 'وجبة وعاء الكينوا والزبادي والتفاح محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Apple Quinoa Yogurt Bowl meal calculated from the listed ingredient weights.', 'breakfast'::public.meal_type, ARRAY['maintenance','muscle_gain']::text[], ARRAY['vegetarian']::text[], ARRAY['milk','tree_nuts']::text[], 471, 27.7, 64.5, 11.3, 463, 'g', 1, ARRAY['ضع الكينوا المطبوخة في وعاء.','أضف الزبادي اليوناني فوقها.','أضف قطع التفاح واللوز ورشّ العسل وقدّم.']::text[], ARRAY['Add the cooked quinoa to a bowl.','Spoon the Greek yogurt over the quinoa.','Top with apple, almonds, and honey. Serve.']::text[], 8, '/nutrition/meals/MEAL-004/cover.webp', '/nutrition/meals/MEAL-004/cover-thumb.webp', 'images/MEAL-004.png', 'ready'::public.meal_image_status, 'وعاء الكينوا والزبادي والتفاح', 'Apple Quinoa Yogurt Bowl', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "20_29", "carb_band_g": "high", "fat_band_g": "moderate", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 454, "macro_energy_kcal": 471, "macro_vs_ingredient_delta_pct": 3.8, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 4),
('MEAL-005', 'دجاج مشوي مع الأرز والخضار', 'Grilled Chicken, Rice & Vegetables', 'وجبة دجاج مشوي مع الأرز والخضار محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Grilled Chicken, Rice & Vegetables meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['fat_loss','maintenance','muscle_gain']::text[], ARRAY['high_protein']::text[], ARRAY[]::text[], 622, 57.5, 64.5, 14.9, 528, 'g', 1, ARRAY['اشوِ صدر الدجاج حتى ينضج تمامًا ثم قطّعه.','سخّن الأرز واطبخ البروكلي والجزر.','قدّم المكونات مع زيت الزيتون.']::text[], ARRAY['Grill the chicken breast until cooked through, then slice.','Warm the rice and cook the broccoli and carrots.','Plate the meal and finish with olive oil.']::text[], 30, '/nutrition/meals/MEAL-005/cover.webp', '/nutrition/meals/MEAL-005/cover-thumb.webp', 'images/MEAL-005.png', 'ready'::public.meal_image_status, 'دجاج مشوي مع الأرز والخضار', 'Grilled Chicken, Rice & Vegetables', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "600_plus", "protein_band_g": "40_plus", "carb_band_g": "high", "fat_band_g": "moderate", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 632, "macro_energy_kcal": 622, "macro_vs_ingredient_delta_pct": 1.5, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 5),
('MEAL-006', 'سلمون مع البطاطس والبروكلي', 'Salmon, Potato & Broccoli', 'وجبة سلمون مع البطاطس والبروكلي محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Salmon, Potato & Broccoli meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['maintenance','muscle_gain']::text[], ARRAY['pescatarian','omega_3']::text[], ARRAY['fish']::text[], 591, 40.1, 52.9, 24.3, 495, 'g', 1, ARRAY['اخبز السلمون حتى ينضج ويتفكك بسهولة.','اخبز البطاطس واطبخ البروكلي.','قدّم مع زيت الزيتون.']::text[], ARRAY['Bake the salmon until it flakes easily.','Bake the potato and cook the broccoli.','Serve with olive oil.']::text[], 30, '/nutrition/meals/MEAL-006/cover.webp', '/nutrition/meals/MEAL-006/cover-thumb.webp', 'images/MEAL-006.png', 'ready'::public.meal_image_status, 'سلمون مع البطاطس والبروكلي', 'Salmon, Potato & Broccoli', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "40_plus", "carb_band_g": "high", "fat_band_g": "high", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 587, "macro_energy_kcal": 591, "macro_vs_ingredient_delta_pct": 0.8, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 6),
('MEAL-007', 'وعاء اللحم والبرغل', 'Beef & Bulgur Bowl', 'وجبة وعاء اللحم والبرغل محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Beef & Bulgur Bowl meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['maintenance','muscle_gain']::text[], ARRAY['high_protein']::text[], ARRAY['gluten']::text[], 569, 46.3, 41, 24.4, 536, 'g', 1, ARRAY['اطه اللحم المفروم حتى ينضج تمامًا.','سخّن البرغل.','أضف الطماطم والخيار وزيت الزيتون وقدّم.']::text[], ARRAY['Cook the ground beef until fully done.','Warm the bulgur.','Add tomato, cucumber, and olive oil. Serve.']::text[], 25, '/nutrition/meals/MEAL-007/cover.webp', '/nutrition/meals/MEAL-007/cover-thumb.webp', 'images/MEAL-007.png', 'ready'::public.meal_image_status, 'وعاء اللحم والبرغل', 'Beef & Bulgur Bowl', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "40_plus", "carb_band_g": "moderate", "fat_band_g": "high", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 561, "macro_energy_kcal": 569, "macro_vs_ingredient_delta_pct": 1.4, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 7),
('MEAL-008', 'سلطة تونة ومعكرونة', 'Tuna Pasta Salad', 'وجبة سلطة تونة ومعكرونة محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Tuna Pasta Salad meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['fat_loss','maintenance']::text[], ARRAY['high_protein','pescatarian']::text[], ARRAY['fish','gluten','milk']::text[], 563, 55.4, 76.1, 4.1, 550, 'g', 1, ARRAY['صفِّ التونة جيدًا.','اخلط المعكرونة المبردة مع التونة والذرة والخيار.','أضف الزبادي اليوناني واخلط ثم قدّم باردة.']::text[], ARRAY['Drain the tuna well.','Combine the cooled pasta with tuna, corn, and cucumber.','Mix in the Greek yogurt and serve cold.']::text[], 18, '/nutrition/meals/MEAL-008/cover.webp', '/nutrition/meals/MEAL-008/cover-thumb.webp', 'images/MEAL-008.png', 'ready'::public.meal_image_status, 'سلطة تونة ومعكرونة', 'Tuna Pasta Salad', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "40_plus", "carb_band_g": "high", "fat_band_g": "low", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 564, "macro_energy_kcal": 563, "macro_vs_ingredient_delta_pct": 0.2, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 8),
('MEAL-009', 'لفافة ديك رومي وأفوكادو', 'Turkey Avocado Wrap', 'وجبة لفافة ديك رومي وأفوكادو محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Turkey Avocado Wrap meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['fat_loss','maintenance']::text[], ARRAY['high_protein']::text[], ARRAY['gluten','milk']::text[], 510, 49.5, 43.7, 15.2, 405, 'g', 1, ARRAY['مدّ الزبادي اليوناني على التورتيلا.','أضف الديك الرومي والأفوكادو والخس والطماطم.','لفّ التورتيلا بإحكام ثم قطّعها وقدّم.']::text[], ARRAY['Spread the Greek yogurt on the tortilla.','Add turkey, avocado, lettuce, and tomato.','Wrap tightly, slice, and serve.']::text[], 12, '/nutrition/meals/MEAL-009/cover.webp', '/nutrition/meals/MEAL-009/cover-thumb.webp', 'images/MEAL-009.png', 'ready'::public.meal_image_status, 'لفافة ديك رومي وأفوكادو', 'Turkey Avocado Wrap', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "40_plus", "carb_band_g": "moderate", "fat_band_g": "moderate", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 502, "macro_energy_kcal": 510, "macro_vs_ingredient_delta_pct": 1.6, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 9),
('MEAL-010', 'وعاء حمص وكينوا بالطحينة', 'Chickpea Quinoa Tahini Bowl', 'وجبة وعاء حمص وكينوا بالطحينة محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Chickpea Quinoa Tahini Bowl meal calculated from the listed ingredient weights.', 'lunch'::public.meal_type, ARRAY['maintenance','muscle_gain']::text[], ARRAY['vegan','high_fiber']::text[], ARRAY['sesame']::text[], 615, 25.9, 89.2, 17.2, 538, 'g', 1, ARRAY['ضع الحمص والكينوا في وعاء.','أضف الخيار والطماطم.','خفف الطحينة بقليل من الماء واخلطها ثم صبّها فوق الوجبة.']::text[], ARRAY['Add the chickpeas and quinoa to a bowl.','Add cucumber and tomato.','Thin the tahini with a little water, drizzle over the bowl, and serve.']::text[], 15, '/nutrition/meals/MEAL-010/cover.webp', '/nutrition/meals/MEAL-010/cover-thumb.webp', 'images/MEAL-010.png', 'ready'::public.meal_image_status, 'وعاء حمص وكينوا بالطحينة', 'Chickpea Quinoa Tahini Bowl', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "600_plus", "protein_band_g": "20_29", "carb_band_g": "high", "fat_band_g": "moderate", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 595, "macro_energy_kcal": 615, "macro_vs_ingredient_delta_pct": 3.4, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 10),
('MEAL-011', 'شوربة عدس مع خبز كامل', 'Lentil Soup with Whole-Wheat Bread', 'وجبة شوربة عدس مع خبز كامل محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Lentil Soup with Whole-Wheat Bread meal calculated from the listed ingredient weights.', 'dinner'::public.meal_type, ARRAY['fat_loss','maintenance']::text[], ARRAY['vegan','high_fiber']::text[], ARRAY['gluten']::text[], 553, 32, 86.1, 8.9, 515, 'g', 1, ARRAY['اطه العدس مع الجزر والطماطم حتى يتماسك القوام.','أضف زيت الزيتون.','قدّم الشوربة مع خبز القمح الكامل.']::text[], ARRAY['Simmer the lentils with carrot and tomato until thickened.','Stir in the olive oil.','Serve the soup with the whole-wheat bread.']::text[], 30, '/nutrition/meals/MEAL-011/cover.webp', '/nutrition/meals/MEAL-011/cover-thumb.webp', 'images/MEAL-011.png', 'ready'::public.meal_image_status, 'شوربة عدس مع خبز كامل', 'Lentil Soup with Whole-Wheat Bread', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "30_39", "carb_band_g": "high", "fat_band_g": "low", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 532, "macro_energy_kcal": 553, "macro_vs_ingredient_delta_pct": 3.9, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 11),
('MEAL-012', 'توفو وبطاطا حلوة وخضار', 'Tofu, Sweet Potato & Greens', 'وجبة توفو وبطاطا حلوة وخضار محسوبة من أوزان المكونات المدرجة لحصة واحدة.', 'A single-serving Tofu, Sweet Potato & Greens meal calculated from the listed ingredient weights.', 'dinner'::public.meal_type, ARRAY['fat_loss','maintenance']::text[], ARRAY['vegan']::text[], ARRAY['soy']::text[], 594, 38.4, 59.2, 22.6, 526, 'g', 1, ARRAY['اخبز البطاطا الحلوة حتى تطرى.','حمّر التوفو حتى يكتسب لونًا ذهبيًا.','اطبخ البروكلي وقدّم المكونات مع زيت الزيتون.']::text[], ARRAY['Bake the sweet potato until tender.','Pan-sear the tofu until golden.','Cook the broccoli and serve with olive oil.']::text[], 30, '/nutrition/meals/MEAL-012/cover.webp', '/nutrition/meals/MEAL-012/cover-thumb.webp', 'images/MEAL-012.png', 'ready'::public.meal_image_status, 'توفو وبطاطا حلوة وخضار', 'Tofu, Sweet Potato & Greens', 'pilot'::public.meal_library_status, 'nutrition_library_review_passed_2026-08-16', 'Recipe estimate from USDA generic per-100-g data; brands, drained weights and cooking yield can change values.', '{"calorie_band_kcal": "450_599", "protein_band_g": "30_39", "carb_band_g": "high", "fat_band_g": "high", "meal_type_required": true, "max_calorie_delta_pct": 10, "max_protein_delta_g": 8, "exclude_allergens": true}'::jsonb, '{"ingredient_energy_kcal": 552, "macro_energy_kcal": 594, "macro_vs_ingredient_delta_pct": 7.6, "macro_formula": "protein_g*4 + carbs_g*4 + fat_g*9"}'::jsonb, TRUE, 12),
